#include <iostream>
#include <queue>
#include <vector>

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* next = nullptr) : val(x), next(next) {}
};

// Reads a count and that many values, and links them into nodes.
ListNode* readList() {
    int n;
    std::cin >> n;
    std::vector<int> values(n);
    for (int i = 0; i < n; i++) {
        std::cin >> values[i];
    }
    ListNode* head = nullptr;
    for (int i = n - 1; i >= 0; i--) {
        head = new ListNode(values[i], head);
    }
    return head;
}

void printList(ListNode* head) {
    if (head == nullptr) {
        std::cout << "empty\n";
        return;
    }
    for (ListNode* node = head; node != nullptr; node = node->next) {
        std::cout << node->val << (node->next != nullptr ? " " : "\n");
    }
}

ListNode* mergeKLists(const std::vector<ListNode*>& lists) {
    // The top of a priority_queue is its "largest" item, so a node ranks
    // below another when its value is bigger, and the smallest value is on top.
    auto biggerValue = [](const ListNode* a, const ListNode* b) { return a->val > b->val; };
    std::priority_queue<ListNode*, std::vector<ListNode*>, decltype(biggerValue)> heap(biggerValue);
    for (ListNode* head : lists) {
        if (head != nullptr) {
            heap.push(head);
        }
    }
    ListNode dummy;  // sits before the result's head
    ListNode* tail = &dummy;
    while (!heap.empty()) {
        ListNode* node = heap.top();
        heap.pop();
        tail->next = node;
        tail = node;
        if (node->next != nullptr) {
            heap.push(node->next);
        }
    }
    return dummy.next;
}

int main() {
    int k;
    std::cin >> k;
    std::vector<ListNode*> lists(k);
    for (int i = 0; i < k; i++) {
        lists[i] = readList();
    }
    printList(mergeKLists(lists));
    return 0;
}

